define(function(){'use strict';return function(address){const formattedAddress={firstName:address.firstname,lastName:address.lastname,company:address.company,locality:address.city,region:address.regionCode,postalCode:address.postcode,countryCodeAlpha2:address.countryId,phoneNumber:address.telephone};formattedAddress.streetAddress=address.street?.[0];if(address.street?.[1]){formattedAddress.extendedAddress=address.street.slice(1).join(', ');}
return formattedAddress;};});